from __future__ import annotations

from ..wts.edaemon import Edaemon
from ..wts.state_machine import WTSStateMachine
from .common import WTSCommonInterface


class WTSEdaemonInterface(WTSCommonInterface):

    def setup_edaemon(
        self,
        edaemon_port: int,
        host_ip: str = "127.0.0.1",
        tool_dir: str | None = None,
        **kwargs,
    ) -> None:
        """
        Set up WTSSIM library to work with edaemon.

        Library is working through:

        * SSHClient to start/stop edaemon services.

        :param integer edaemon_port:  Edaemon process port.
        :param string  host_ip:       IP address of the remote/local machine.
        :param string  tool_dir:      Path to the directory where the edaemon binary is available.

        |

        :Supported SSH parameters are available via kwargs:
            * **ssh_user** (string)   - Username for SSH authentication. Default is 'ute'.
            * **ssh_pass** (string)   - Password for SSH authentication. Default is 'ute'.
            * **ssh_port** (integer)  - SSH service port on specified machine. Default is 22.
            * **ssh_prompt** (string) - SSH prompt received after logging in. Default is '$ '.

        :Note:
            Since v.2.2.0 the ``ssh_prompt`` argument is obsolete and has no effect!


        It is possible to change kwargs parameters by using syntax like in example below:
        ::

            Some keyword     ssh_user=test_user    ssh_pass=test_pass    ssh_port=22    ssh_prompt=$
        """
        alias = kwargs.get("alias")
        connection_settings = self._configure_ssh_connection(
            host_ip,
            kwargs.get("ssh_user"),
            kwargs.get("ssh_pass"),
            kwargs.get("ssh_port"),
        )
        ssh_client = self._create_ssh_client_from_settings(connection_settings)
        edaemon = self._create_edaemons([edaemon_port], ssh_client, tool_dir)[0]
        self._store_edaemon(edaemon, alias)

    def teardown_edaemon(self, **kwargs) -> None:
        """
        Stop and remove connection of edaemon.

        :note: This teardown does not tear down egate or wts application.
        """
        alias = kwargs.get("alias")
        edaemon = self.edaemon_store.get(alias)  # type: WTSStateMachine
        edaemon.stop()
        edaemon.close_all_connections()
        self.edaemon_store.remove(alias)

    def teardown_all_aliases_for_edaemon(
        self, collect_logs: bool | None = True, **kwargs
    ) -> None:
        """
        Stop and remove connection of all aliases of edaemon and if ``collect_logs=True`` collects their log files

        :param boolean collect_logs:  Flag indicating whether to collect logs or not.

        :note: Does not tear down egate and wts applications
        """
        if collect_logs:
            for alias_name_edaemon in self.edaemon_aliases:
                self.collect_edaemon_log_files(alias=alias_name_edaemon)
                self.teardown_edaemon(alias=alias_name_edaemon)
        else:
            for alias_name_edaemon in self.edaemon_aliases:
                self.teardown_edaemon(alias=alias_name_edaemon)

    def start_edaemon_process(self, **kwargs) -> None:
        """Start the edaemon process."""

        alias = kwargs.get("alias")
        self.edaemon_store.get(alias).start()

    def collect_edaemon_log_files(
        self, unzip: bool | None = None, subdirectory: str | None = None, **kwargs
    ) -> None:
        """
        Download created log files to the test result directory.

        :param boolean unzip:        Flag indicating whether collected logs should be extracted.
        :param string  subdirectory: Name of folder to create in addition to the normal test result structure.

        |

        :Supported SSH parameters are available via kwargs:
            * **ssh_user**   (string)  - Username for SSH authentication. Default is 'ute'.
            * **ssh_pass**   (string)  - Password for SSH authentication. Default is 'ute'.
            * **ssh_port**   (integer) - SSH service port on specified machine. Default is 22.
            * **ssh_prompt** (string)  - SSH prompt received after logging in. Default is '$ '.

        It is possible to change kwargs parameters by using syntax like in example below:
        ::

            Some keyword     ssh_user=test_user    ssh_pass=test_pass    ssh_port=22    ssh_prompt=$

        This method will download the following files:

        * edaemon.log
        * mme_*.log
        * pgw_*.log
        * sgw_*.log
        * uec_*.log


        :note: Format of the result directory structure is: TestSuite1/TestSuite2/TestCase/SubFolder.
        """
        alias = kwargs.get("alias")
        wts = self.edaemon_store.get(alias)
        self._collect_logs(wts, unzip, subdirectory)

    def _store_edaemon(self, edaemon: Edaemon, alias: str) -> None:
        wts = WTSStateMachine(alias=alias)
        wts.edaemons.append(edaemon)
        self.edaemon_store.add(wts, alias=alias)
